BEGIN;
CREATE TABLE IF NOT EXISTS source_policies(source_id text PRIMARY KEY REFERENCES sources(id),registry jsonb NOT NULL,usage_mode text NOT NULL CHECK(usage_mode IN ('LIVE_PROXY','CACHED_METADATA','LICENSED_IMPORT','LINK_ONLY','FUTURE_DISABLED')),enabled boolean NOT NULL DEFAULT false,metadata_allowed boolean NOT NULL DEFAULT false,offline_metadata_allowed boolean NOT NULL DEFAULT false,clinical_text_allowed boolean NOT NULL DEFAULT false,license_evidence_url text NOT NULL CHECK(license_evidence_url LIKE 'https://%'),terms_checked_at date,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS qualified_reviewers(id text PRIMARY KEY,display_name text NOT NULL,qualification_evidence text NOT NULL,verified_by text NOT NULL,verified_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS canonical_concepts(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('ingredient','precise_ingredient','clinical_drug','product','chemical_compound','research','disease_topic','anatomy_term','source_reference')),preferred_name text NOT NULL,arabic_name text,latin_name text,translation_state text NOT NULL DEFAULT 'needs_review' CHECK(translation_state IN ('needs_review','approved')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published_metadata','withdrawn')),source_id text NOT NULL REFERENCES sources(id),source_native_id text NOT NULL,normalized_search text NOT NULL,stale boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1 CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS concept_identifiers(concept_id uuid NOT NULL REFERENCES canonical_concepts(id),scheme text NOT NULL CHECK(scheme IN ('RxCUI','SPL_SET_ID','NDC','UNII','PubChemCID','InChIKey','DOI','PMID','PMCID','NCT','MeSH','ICD11','SNOMED','ATC')),value text NOT NULL,entity_kind text NOT NULL,source_id text NOT NULL REFERENCES sources(id),source_native_id text NOT NULL,verified_at timestamptz NOT NULL,PRIMARY KEY(concept_id,scheme,value),UNIQUE(scheme,value,entity_kind));
CREATE TABLE IF NOT EXISTS concept_aliases(concept_id uuid NOT NULL REFERENCES canonical_concepts(id),locale text NOT NULL,alias text NOT NULL,normalized text NOT NULL,source_id text NOT NULL REFERENCES sources(id),review_state text NOT NULL DEFAULT 'needs_review',PRIMARY KEY(concept_id,locale,alias));
CREATE TABLE IF NOT EXISTS source_records(source_id text NOT NULL REFERENCES sources(id),source_native_id text NOT NULL,canonical_id uuid REFERENCES canonical_concepts(id),payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),snapshot jsonb NOT NULL CHECK(snapshot @> '{"content_class":"metadata"}'::jsonb AND NOT(snapshot ? 'abstract') AND NOT(snapshot ? 'fullText') AND NOT(snapshot ? 'raw_text') AND (snapshot #> '{metadata,abstract}') IS NULL AND (snapshot #> '{metadata,fullText}') IS NULL),canonical_url text NOT NULL CHECK(canonical_url LIKE 'https://%'),fetched_at timestamptz NOT NULL,source_updated_at timestamptz,response_etag text,last_modified text,review_state text NOT NULL DEFAULT 'needs_review',revision integer NOT NULL DEFAULT 1,PRIMARY KEY(source_id,source_native_id));
CREATE TABLE IF NOT EXISTS source_record_versions(source_id text NOT NULL,source_native_id text NOT NULL,payload_hash text NOT NULL,snapshot jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source_id,source_native_id,payload_hash),FOREIGN KEY(source_id,source_native_id) REFERENCES source_records(source_id,source_native_id));
CREATE TABLE IF NOT EXISTS concept_relations(from_concept uuid NOT NULL REFERENCES canonical_concepts(id),relation text NOT NULL CHECK(relation IN ('contains_ingredient','has_identifier_link','related_research','source_topic')),to_concept uuid NOT NULL REFERENCES canonical_concepts(id),source_id text NOT NULL,source_native_id text NOT NULL,evidence jsonb NOT NULL,CHECK(from_concept<>to_concept),PRIMARY KEY(from_concept,relation,to_concept,source_id),FOREIGN KEY(source_id,source_native_id) REFERENCES source_records(source_id,source_native_id));
CREATE TABLE IF NOT EXISTS source_fetch_jobs(id uuid PRIMARY KEY,source_id text NOT NULL REFERENCES sources(id),idempotency_key text NOT NULL UNIQUE,request_hash text NOT NULL,request_shape jsonb NOT NULL,attempts integer NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN ('running','completed','failed')),cursor_value text,items_seen integer NOT NULL DEFAULT 0,imported integer NOT NULL DEFAULT 0,updated integer NOT NULL DEFAULT 0,skipped integer NOT NULL DEFAULT 0,duplicates integer NOT NULL DEFAULT 0,quarantined integer NOT NULL DEFAULT 0,failed integer NOT NULL DEFAULT 0,request_count integer NOT NULL DEFAULT 0,response_bytes bigint NOT NULL DEFAULT 0,cache_hits integer NOT NULL DEFAULT 0,duration_ms integer NOT NULL DEFAULT 0,error_code text CHECK(error_code ~ '^[a-z_]+$'),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE TABLE IF NOT EXISTS source_connector_status(source_id text PRIMARY KEY REFERENCES sources(id),health_status text NOT NULL DEFAULT 'unknown',last_success_at timestamptz,last_error_at timestamptz,error_code text CHECK(error_code ~ '^[a-z_]+$'),consecutive_failures integer NOT NULL DEFAULT 0,circuit_until timestamptz,last_job_id uuid REFERENCES source_fetch_jobs(id));
CREATE TABLE IF NOT EXISTS article_candidates(id uuid PRIMARY KEY,source_id text NOT NULL,source_native_id text NOT NULL,payload_hash text NOT NULL,concept_id uuid REFERENCES canonical_concepts(id),reason text NOT NULL,status text NOT NULL DEFAULT 'needs_review' CHECK(status IN ('needs_review','quarantined','rejected','approved')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(source_id,source_native_id) REFERENCES source_records(source_id,source_native_id),UNIQUE(source_id,source_native_id,payload_hash));
CREATE TABLE IF NOT EXISTS knowledge_facts(id uuid PRIMARY KEY,concept_id uuid NOT NULL REFERENCES canonical_concepts(id),claim_type text NOT NULL CHECK(claim_type IN ('identity','name','formula','molecular_weight','bibliographic','clinical','dosing')),claim_value jsonb NOT NULL,locale text NOT NULL DEFAULT 'en',source_id text NOT NULL,source_native_id text NOT NULL,canonical_url text NOT NULL,source_section text NOT NULL,revision integer NOT NULL DEFAULT 1,provenance_snapshot jsonb NOT NULL,payload_hash text NOT NULL,fetched_at timestamptz NOT NULL,source_updated_at timestamptz,reviewed_at timestamptz,reviewer_id text REFERENCES qualified_reviewers(id),review_outcome text NOT NULL DEFAULT 'needs_review',evidence_class text NOT NULL,jurisdiction text,population_context text,license text NOT NULL,permitted_display_mode text NOT NULL CHECK(permitted_display_mode IN ('metadata','source_link_only','licensed_text')),publish_state text NOT NULL DEFAULT 'draft' CHECK(publish_state IN ('draft','published','withdrawn')),stale_state boolean NOT NULL DEFAULT false,conflict_flag boolean NOT NULL DEFAULT false,FOREIGN KEY(source_id,source_native_id) REFERENCES source_records(source_id,source_native_id),CHECK(claim_type NOT IN ('clinical','dosing') OR publish_state<>'published' OR (reviewer_id IS NOT NULL AND reviewed_at IS NOT NULL AND review_outcome='approved')),UNIQUE(concept_id,claim_type,locale,source_id,source_native_id,payload_hash));
CREATE TABLE IF NOT EXISTS reference_works(concept_id uuid PRIMARY KEY REFERENCES canonical_concepts(id),doi text UNIQUE,pmid text UNIQUE,pmcid text UNIQUE,bibliography jsonb NOT NULL,retraction_state text NOT NULL DEFAULT 'unknown' CHECK(retraction_state IN ('unknown','notice','retracted','corrected')),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS citation_links(id uuid PRIMARY KEY,concept_id uuid REFERENCES canonical_concepts(id),content_id text REFERENCES content_items(canonical_id),reference_id uuid NOT NULL REFERENCES reference_works(concept_id),source_id text NOT NULL,source_native_id text NOT NULL,relation_context text NOT NULL DEFAULT 'bibliographic_mention_not_clinical_evidence',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(concept_id,reference_id,source_id,source_native_id),CHECK(concept_id IS NOT NULL OR content_id IS NOT NULL),FOREIGN KEY(source_id,source_native_id) REFERENCES source_records(source_id,source_native_id));
CREATE TABLE IF NOT EXISTS source_conflicts(id uuid PRIMARY KEY,case_key text NOT NULL UNIQUE,kind text NOT NULL,identifiers jsonb NOT NULL,record_refs jsonb NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS translation_reviews(concept_id uuid NOT NULL REFERENCES canonical_concepts(id),locale text NOT NULL,revision integer NOT NULL,text_value text NOT NULL,status text NOT NULL DEFAULT 'needs_review' CHECK(status IN ('needs_review','approved','rejected')),reviewer_id text REFERENCES qualified_reviewers(id),reviewed_at timestamptz,PRIMARY KEY(concept_id,locale,revision),CHECK(status<>'approved' OR (reviewer_id IS NOT NULL AND reviewed_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS content_change_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_id text NOT NULL,source_native_id text NOT NULL,previous_hash text,new_hash text NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS content_pack_exports(pack_id text NOT NULL,version integer NOT NULL,source_policy_snapshot jsonb NOT NULL,record_count integer NOT NULL,metadata_only boolean NOT NULL DEFAULT true,exported_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(pack_id,version),FOREIGN KEY(pack_id,version) REFERENCES content_packs(id,version));
ALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS details jsonb NOT NULL DEFAULT '{}';
ALTER TABLE content_items ADD COLUMN IF NOT EXISTS source_stale boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION guard_knowledge_publication() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.publish_state='published' THEN IF NOT EXISTS(SELECT 1 FROM source_policies p WHERE p.source_id=NEW.source_id AND p.enabled AND p.metadata_allowed) THEN RAISE EXCEPTION 'source rights do not permit publication'; END IF; IF NEW.claim_type IN ('clinical','dosing') AND (NOT EXISTS(SELECT 1 FROM qualified_reviewers r WHERE r.id=NEW.reviewer_id AND r.active) OR NOT EXISTS(SELECT 1 FROM source_policies p WHERE p.source_id=NEW.source_id AND p.clinical_text_allowed)) THEN RAISE EXCEPTION 'qualified review and clinical reuse rights required'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER knowledge_publication_guard BEFORE INSERT OR UPDATE ON knowledge_facts FOR EACH ROW EXECUTE FUNCTION guard_knowledge_publication();
CREATE OR REPLACE FUNCTION flag_source_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.payload_hash<>NEW.payload_hash THEN INSERT INTO content_change_events(source_id,source_native_id,previous_hash,new_hash,kind) VALUES(NEW.source_id,NEW.source_native_id,OLD.payload_hash,NEW.payload_hash,'source_changed_requires_review'); UPDATE knowledge_facts SET stale_state=true WHERE source_id=NEW.source_id AND source_native_id=NEW.source_native_id AND payload_hash<>NEW.payload_hash; UPDATE canonical_concepts SET stale=true WHERE id=NEW.canonical_id; END IF; RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER source_change_guard AFTER UPDATE ON source_records FOR EACH ROW EXECUTE FUNCTION flag_source_change();
CREATE OR REPLACE FUNCTION flag_retracted_reference() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.retraction_state IN ('retracted','corrected') AND NEW.retraction_state IS DISTINCT FROM OLD.retraction_state THEN UPDATE canonical_concepts SET stale=true WHERE id IN (SELECT concept_id FROM citation_links WHERE reference_id=NEW.concept_id); UPDATE content_items SET source_stale=true,status=CASE WHEN clinical THEN 'needs_review' ELSE status END,review_status=CASE WHEN clinical THEN 'needs_review' ELSE review_status END WHERE canonical_id IN (SELECT content_id FROM citation_links WHERE reference_id=NEW.concept_id); INSERT INTO content_change_events(source_id,source_native_id,new_hash,kind) SELECT source_id,source_native_id,'reference-status',NEW.retraction_state FROM canonical_concepts WHERE id=NEW.concept_id; END IF; RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER reference_withdrawal_guard AFTER UPDATE ON reference_works FOR EACH ROW EXECUTE FUNCTION flag_retracted_reference();
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS concept_normalized_search ON canonical_concepts USING gin(normalized_search gin_trgm_ops);
CREATE INDEX IF NOT EXISTS aliases_normalized_search ON concept_aliases USING gin(normalized gin_trgm_ops);
CREATE INDEX IF NOT EXISTS concept_kind_status ON canonical_concepts(kind,status,id);
CREATE INDEX IF NOT EXISTS concept_updated ON canonical_concepts(updated_at,id);
CREATE INDEX IF NOT EXISTS alias_lookup ON concept_aliases(normalized,concept_id);
CREATE INDEX IF NOT EXISTS source_record_freshness ON source_records(source_id,fetched_at);
CREATE INDEX IF NOT EXISTS job_source_started ON source_fetch_jobs(source_id,started_at);
CREATE INDEX IF NOT EXISTS fact_source_version ON knowledge_facts(source_id,source_native_id,payload_hash);
CREATE INDEX IF NOT EXISTS citation_reference ON citation_links(reference_id);
CREATE OR REPLACE VIEW public_medical_sources AS SELECT s.id,s.source_title,s.source_url,s.publisher,s.license,s.attribution,p.registry,p.usage_mode,p.offline_metadata_allowed,p.terms_checked_at,coalesce(c.health_status,'unknown') AS health_status,c.last_success_at,c.last_error_at,c.error_code FROM sources s JOIN source_policies p ON p.source_id=s.id LEFT JOIN source_connector_status c ON c.source_id=s.id;
CREATE OR REPLACE VIEW public_concepts AS SELECT c.id,c.kind,c.preferred_name,c.arabic_name,c.latin_name,c.translation_state,c.source_id,c.source_native_id,c.normalized_search,c.stale,c.revision,c.updated_at,'needs_review'::text AS clinical_review_state FROM canonical_concepts c JOIN source_policies p ON p.source_id=c.source_id WHERE c.status='published_metadata' AND p.enabled AND p.metadata_allowed;
CREATE OR REPLACE VIEW public_concept_identifiers AS SELECT i.* FROM concept_identifiers i JOIN public_concepts c ON c.id=i.concept_id;
CREATE OR REPLACE VIEW public_knowledge_facts AS SELECT f.* FROM knowledge_facts f JOIN public_concepts c ON c.id=f.concept_id JOIN source_policies p ON p.source_id=f.source_id WHERE f.publish_state='published' AND p.enabled AND p.metadata_allowed AND (f.claim_type NOT IN ('clinical','dosing') OR (f.review_outcome='approved' AND f.reviewed_at IS NOT NULL AND p.clinical_text_allowed AND EXISTS(SELECT 1 FROM qualified_reviewers r WHERE r.id=f.reviewer_id AND r.active)));
CREATE OR REPLACE VIEW public_references AS SELECT w.* FROM reference_works w JOIN public_concepts c ON c.id=w.concept_id;
CREATE OR REPLACE VIEW public_citation_links AS SELECT l.* FROM citation_links l JOIN public_references r ON r.concept_id=l.reference_id WHERE (l.concept_id IN (SELECT id FROM public_concepts) OR l.content_id IN (SELECT canonical_id FROM public_content));
GRANT SELECT ON public_medical_sources,public_concepts,public_concept_identifiers,public_knowledge_facts,public_references,public_citation_links TO dawa_reader;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
INSERT INTO schema_migrations(version) VALUES(4) ON CONFLICT DO NOTHING;
COMMIT;
